  InputGroupInput,
  InputGroupAddon,
  InputGroupButton,
} from "@/registry/erbium/ui/input-group";

const Example = () => {
  const [value, setValue] = useState("https://erbium.dev");

  return (
    <InputGroup className="w-80">
      <InputGroupInput
        value={value}
        onChange={(event) => {
